### Realtime streams

-   Consume messages, deletions, typing, and receipts with AsyncThrowingStream.
-   An edit arrives on `onMessage` as an `update` carrying the new `revision` (keep the higher revision when rows meet); a deletion arrives on `onMessageDeleted` as the message ID.

```swift
let realtime = try convoKit.realtime

// Keep these tasks in the screen's state owner and cancel them on disposal.
// Each stream runs independently so one does not block the others.
let messagesTask = Task {
    do {
        for try await event in realtime.onMessage(conversationId: room.id) {
            // event.type is insert or update; an edit arrives as an update carrying
            // the new event.message.revision, so merge by ID and keep the higher one.
            await viewModel.handleMessageEvent(event)
        }
    } catch { await viewModel.showError(error) }
}

let deletionsTask = Task {
    do {
        for try await event in realtime.onMessageDeleted(conversationId: room.id) {
            await viewModel.removeMessage(event.id) // keep the ID so a late row cannot restore it
        }
    } catch { await viewModel.showError(error) }
}

let typingTask = Task {
    do {
        for try await event in realtime.onTyping(conversationId: room.id) {
            await viewModel.setTyping(event.userId, event.isTyping)
        }
    } catch { await viewModel.showError(error) }
}

let receiptsTask = Task {
    do {
        for try await event in realtime.onReadReceipt(conversationId: room.id) {
            await viewModel.setReadState(event.userId, event.readPosition, event.readAt)
        }
    } catch { await viewModel.showError(error) }
}

// When the screen is disposed:
// messagesTask.cancel()
// deletionsTask.cancel()
// typingTask.cancel()
// receiptsTask.cancel()
```

### Durable read receipts

`Participant.readPosition` and `ReadEvent.readPosition` carry a `ReadPosition` (`messageId`, `createdAt`) beside the acknowledgement time. Resolve readers with `readThrough` instead of comparing timestamps.

```swift
// Participants carry a read position beside the acknowledgement time.
// The position decides by conversation order; lastReadAt is the fallback.
let readers = room.participants.filter { participant in
    participant.appUserId != message.senderId &&
    readThrough(
        position: participant.readPosition,
        lastReadAt: participant.lastReadAt,
        message: message
    )
}

// Merge live events, keeping the newest position per user.
for try await event in realtime.onReadReceipt(conversationId: room.id) {
    readAtByUserId[event.userId] = event.readAt
    guard let incoming = event.readPosition else { continue }
    if let current = readPositionByUserId[event.userId],
       (current.createdAt, current.messageId) >= (incoming.createdAt, incoming.messageId) {
        continue
    }
    readPositionByUserId[event.userId] = incoming
}
```

### Error handling

-   `ConvoKitError` carries a stable `code` plus HTTP status and response body when available.
-   A read whose target is not a message in that conversation fails with status 404 and code `MESSAGE_NOT_FOUND`; a membership failure keeps `HTTP_ERROR`.
-   `listInbox` rejects a `limit` outside 1...100, and the read, clear and edit calls a `privateStateVersion`, `ifVersion` or `revision` outside 0...2147483647, with code `INVALID_ARGUMENT` before any request; a cursor ConvoKit did not issue fails with status 400 and code `INVALID_CURSOR`, and a page the SDK cannot decode fails with `INVALID_RESPONSE`.
-   `editMessage` with a stale `revision` fails with status 409 and code `REVISION_CONFLICT` (nothing was written: reload the row with `getMessage` and retry); another member's message or a `READ` role fails with status 403 and `HTTP_ERROR`; a message the caller cannot see, or one already deleted, fails with status 404 and code `MESSAGE_NOT_FOUND` on `editMessage`, `deleteMessage` and `getMessage` alike.
-   Against an older backend the author calls fail with status 404 and `HTTP_ERROR`, which is never a deleted message.

```swift
do {
    try await convoKit.markConversationRead(
        room.id,
        throughMessageId: newestRendered.id
    )
} catch let error as ConvoKitError where error.code == "MESSAGE_NOT_FOUND" {
    // The target is no longer in this conversation:
    // acknowledge the next newest rendered message instead.
}

do {
    _ = try await convoKit.editMessage(message.id, text: draft, revision: message.revision)
} catch let error as ConvoKitError where error.code == "REVISION_CONFLICT" {
    // Stale revision: reload the message, show it, and retry with its revision.
} catch let error as ConvoKitError where error.code == "MESSAGE_NOT_FOUND" {
    // Deleted or no longer accessible: remove the row.
}
```

Client surface

### One native contract across chat, media, and realtime

The SDK mirrors ConvoKit's client-authorized API surface and leaves administrative membership changes on your backend.

### Session and users

`connectUser / disconnectUser``getUsers / getUser``currentUserId / authHeaders`

### Conversations

`getConversations / getConversation (fills Conversation.membership: your own row)``listInbox(limit: Int = 30, cursor: String? = nil, archived: Bool = false) async throws -> InboxPage``InboxSummary, InboxEntry (Identifiable by conversation.id, with a summary accessor) and InboxPage, with isUnread, unreadMarkedAt and privateStateVersion``createConversation``updateConversationTitle``archive / unarchive / leave``markConversationRead(_:throughMessageId:) and markConversationRead(_:throughMessageId:privateStateVersion:)``markConversationUnread(_:) async throws -> ConversationPrivateState``clearConversationUnread(_:ifVersion:) async throws -> ClearUnreadResult``ConversationMembership (role, lastReadAt, readPosition, unreadMarkedAt, privateStateVersion)``ReadPosition.covers and readThrough(position:lastReadAt:message:)`

### Messages and media

`getMessages / getMessage / sendMessage``editMessage(_:text:revision:) async throws -> Message (author edit; a stale revision fails with status 409 and code REVISION_CONFLICT)``deleteMessage(_:) async throws (author delete; unconditional, cannot be undone)``Message.revision (0 when sent, +1 per edit by its author or your server) and Message.isEdited (revision > 0)``Message.replyToMessageId and SendMessageInput.replyToMessageId (the quoted message of the same room, nil otherwise; write-once)``getReplyPreviews(conversationId:messageIds:) async throws -> [ReplyPreview] (one round trip per rendered page; the ids are trimmed, de-duplicated in first-seen order and split into requests of 50, and an id missing from a resolved result is the only deletion signal)``getMessageContext(conversationId:messageId:olderCursor:newerCursor:limit:) async throws -> MessageContextPage (one window of history, newest first; exactly one selector and a limit in 1...100, INVALID_ARGUMENT before any request; a centred window always contains its target; MESSAGE_NOT_FOUND for an unknown target and INVALID_CURSOR for an unreadable cursor)``clientMessageId and createClientMessageId()``image, file, location, and contact media``signed uploads and protected downloads``user avatars and conversation images`

### Realtime

`messages as AsyncThrowingStream (MessageEvent: type insert or update, message; an edit is an update carrying the new revision)``onMessageDeleted(conversationId:) for the IDs of deleted messages``onInboxChanged(appId:) for membership, metadata, profile and deletion changes, including after reconnecting``onInboxActivity(appId:) for message sends, edits, read-position advances and your own unread marker changes (empty, never raised on connection; throttle it)``typing and read-receipt streams (ReadEvent carries readPosition)``presence streams``typing, read, and presence publishing`

### Joining by room ID is a backend policy

Knowing an ID is not authorization. Grant membership first, then let the SDK fetch the room as the connected user.

```swift
// Your backend authenticates the host user and enforces room policy.
try await appBackend.joinConvoKitRoom(roomId)

// The iOS app loads the room only after membership is granted.
let room = try await convoKit.getConversation(roomId)
```

### Session lifecycle

Connect the user before creating subscriptions or SDK-backed UI. Your token provider must fetch fresh tokens from your authenticated backend.

On sign-out or account change, dispose the current UI controllers and subscriptions, then disconnect the client. Create a new adapter or controller after the next successful login, even when signing back in as the same user.

See [authentication](https://convokit.app/docs/auth) for the token flow and [messaging behavior](https://convokit.app/docs/messaging) for read receipts, retries, timestamps, and what the SDK-backed UI handles automatically.

Android SDK

# Build native Kotlin chat with coroutines and Flow.

The Android SDK supports API 23+ with conversations, messages, attachments, and realtime events. Keep the ConvoKit client secret on your backend.

Published`app.convokit:convokit-android:0.10.0`

[Maven artifact](https://maven.convokit.app/app/convokit/convokit-android/0.10.0/convokit-android-0.10.0.pom) [Public example](https://github.com/ConvoKitApp/ConvoKit-Android-SDK-Examples) [Compose UI](https://convokit.app/docs/android-ui)

### Native Android, distributed from a public Maven feed

Add the ConvoKit repository and dependency below. No registry login or GitHub token is required. The example shows a working integration.

### Add the repository

Register the unauthenticated ConvoKit feed once.

```kotlin
dependencyResolutionManagement {
    repositories {
        google()
        mavenCentral()
        maven("https://maven.convokit.app/")
    }
}
```

### Add the dependency

Requires Android API 23+, Kotlin 2.1+, and Java 17.

```kotlin
dependencies {
    implementation("app.convokit:convokit-android:0.10.0")
}
```

### The client secret never belongs in an APK

Android receives only the public client ID and a short-lived user token from your authenticated backend. Room membership is also a backend authorization decision—not proof supplied by knowing an ID.

### Configure and connect

Inject your token endpoint through TokenProvider. The SDK uses https://api.convokit.app automatically.

```kotlin
val convoKit = ConvoKitClient(
    clientId = "your-public-client-id",
    tokenProvider = TokenProvider { appUserId ->
        // Call your authenticated backend. Return only the scoped user token.
        yourApi.issueConvoKitToken(appUserId).token
    },
)

lifecycleScope.launch {
    convoKit.connectUser(currentUser.id)
}
```

### Server token endpoint

Keep client credentials on the server.

```javascript
// app is your existing Express app.
// Supply middleware that verifies your product session and sets req.user.
// For cookie sessions, also enforce your product's CSRF protection.
import { requireProductUser } from './your-auth.js'

const clientId = process.env.CONVOKIT_CLIENT_ID
const clientSecret = process.env.CONVOKIT_CLIENT_SECRET
if (!clientId || !clientSecret) throw new Error('Configure ConvoKit server credentials')

async function callConvoKit(path, body) {
  const response = await fetch('https://api.convokit.app/api/v1/' + path, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-client-id': clientId,
      'x-client-secret': clientSecret,
    },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(10_000),
  })
  if (!response.ok) throw new Error('ConvoKit request failed')
  return response.json()
}

app.post('/api/convokit/token', requireProductUser, async (req, res) => {
  res.set('Cache-Control', 'no-store')
  const id = req.user?.id // Trusted session identity, NEVER a request-body ID.
  if (typeof id !== 'string' || !id) {
    return res.status(401).json({ error: 'Sign in first' })
  }
  if (req.body?.appUserId !== undefined && req.body.appUserId !== id) {
    return res.status(403).json({ error: 'User does not match your session' })
  }

  try {
    await callConvoKit('user', { id, name: req.user.name })
    const result = await callConvoKit('auth/token', { appUserId: id })
    if (typeof result?.data?.token !== 'string' || !result.data.token) {
      throw new Error('Invalid token response')
    }
    // The customer-facing endpoint returns { token }, not ConvoKit's envelope.
    return res.json({ token: result.data.token })
  } catch {
    return res.status(502).json({ error: 'Chat token temporarily unavailable' })
  }
})
```

